# 8-2 카피

# LangGraph 병렬 실행을 활용한 검색 및 분석 에이전트 구현
#
# 실행 흐름:
#           ┌── search_agent (Tavily 웹 검색) ────┐
# START ────┤                                     ├── merge_agent ── END
#           └── analysis_agent (LLM 자체 분석) ──┘
#
# Fan-out: 검색 에이전트와 분석 에이전트를 병렬 실행
# Fan-in: 두 에이전트의 실행 결과를 하나로 통합
#
# 검색 에이전트: Tavily를 통해 외부 정보를 검색
# 분석 에이전트: LLM의 기존 지식을 기반으로 질문 분석
# 병합 에이전트: 검색 결과와 분석 결과를 결합하여 최종 응답 생성

################# 0. LLM 설정 #################

from langchain_openai import ChatOpenAI
import os

from dotenv import load_dotenv
load_dotenv()

api_key = os.environ["MONOROUTER_API_KEY"].strip()
base_url = "https://monogpt.kr/api/monorouter/v1/"

llm = ChatOpenAI(
    model_name="gpt-5.6-terra",
    temperature=0, # 응답의 무작위성 설정 (0에 가까울수록 일관된 응답)
    max_tokens=4000, # 최대 출력 토큰 수
    api_key=api_key,
    base_url=base_url,
)


################# 1. Tool 정의 #################

# pip install langchain-tavily
from langchain_tavily import TavilySearch

# TavilySearch: 인터넷에서 최신 정보를 검색하는 외부 검색 도구
web_search = TavilySearch(
    max_results=3,
)

# Tool 단독 실행 테스트
result = web_search.invoke({
    "query": "삼성전자의 오늘 주가"
})

