################# 2. State 정의 #################

from typing import Annotated, TypedDict
from langgraph.graph import StateGraph, START, END
from langgraph.graph.message import add_messages
from langgraph.prebuilt import ToolNode, tools_condition


# State: 그래프의 Node들이 공유하는 데이터 구조
class State(TypedDict):
    messages: Annotated[list, add_messages] # 사용자 질문과 AI 응답을 저장하는 메시지 목록
    search_result: str    # 검색 Node의 실행 결과
    analysis_result: str  # 분석 Node의 실행 결과
    final_result: str     # 검색 및 분석 결과를 통합한 최종 결과


################# 3. Node 정의 #################

# 검색 에이전트
# 사용자 질문을 Tavily에 전달하여 웹 검색 수행
def search_agent(state: State):
    print("검색 에이전트 실행")
    question = state["messages"][-1].content # State의 마지막 메시지에서 사용자 질문 추출
    result = web_search.invoke({ # Tavily 검색 Tool을 직접 호출 # LLM의 Tool Calling을 거치지 않고 검색 실행
        "query": question
    })
    # 검색 결과를 문자열로 변환하여 State에 반환
    # search_result 필드만 업데이트
    return {"search_result": str(result)}


# 분석 에이전트
# LLM의 기존 지식을 활용하여 사용자 질문 분석
def analysis_agent(state: State):
    print("분석 에이전트 실행")
    question = state["messages"][-1].content # State의 마지막 메시지에서 사용자 질문 추출
    response = llm.invoke(  # LLM에 질문을 전달하여 분석 결과 생성
        f"다음 질문을 기존 지식을 바탕으로 분석해줘.\n{question}"
    )
    # LLM 응답의 텍스트를 State에 반환
    # analysis_result 필드만 업데이트
    return {"analysis_result": response.content}

# 결과 병합 에이전트
# 병렬 실행된 검색 결과와 분석 결과를 하나로 통합
def merge_agent(state: State):
    # State에서 검색 결과와 분석 결과를 가져와 문자열로 결합
    result = (
        state["search_result"] + "\n\n" 
        + "========================================================" + "\n"
        + state["analysis_result"]
    )
    # 통합한 결과를 State의 final_result에 저장
    return {"final_result": result}
    # return{"messages": [("assistant", result)]}


################# 4. 그래프 구성, Node 추가 #################

# StateGraph: State를 기반으로 그래프 생성
builder = StateGraph(State)

builder.add_node("search", search_agent)
builder.add_node("analysis", analysis_agent)
builder.add_node("merge", merge_agent)

################# 5. Edge 추가 #################

################# 병렬 실행 (Fan-out) #################
# START에서 search와 analysis Node로 동시에 분기
# 두 Node는 동일한 초기 State를 입력받아 병렬 실행
# 서로 다른 State 필드를 업데이트하므로 병렬 실행 시 충돌하지 않음
builder.add_edge(START, "search")
builder.add_edge(START, "analysis")

################# 결과 병합 (Fan-in) #################
# 검색과 분석 Node가 모두 완료되면 merge Node 실행
# search_result와 analysis_result가 반영된 State를 전달받음
builder.add_edge("search", "merge")
builder.add_edge("analysis", "merge")

builder.add_edge("merge", END)

################# 6. 그래프 컴파일 #################
graph = builder.compile()

################# 7. 그래프 실행 #################
